//! Agreement with Python's reference implementation (`packaging`), from a
//! table generated by `tests/gen_fixture.py`.
use crate::{evaluate, Env, SpecifierSet, Version};
use serde_json::Value;
use std::cmp::Ordering;

fn truth() -> Value {
    serde_json::from_str(include_str!("../tests/packaging_truth.json")).unwrap()
}

fn strings(v: &Value) -> Vec<&str> {
    v.as_array().unwrap().iter().map(|s| s.as_str().unwrap()).collect()
}

#[test]
fn agrees_with_python_packaging_on_what_is_a_version() {
    let t = truth();
    for s in strings(&t["valid"]) {
        assert!(Version::parse(s).is_some(), "{s:?} is a version");
    }
    for s in strings(&t["invalid"]) {
        assert!(Version::parse(s).is_none(), "{s:?} is not a version");
    }
    let pre = strings(&t["prerelease"]);
    for s in strings(&t["valid"]) {
        assert_eq!(Version::parse(s).unwrap().is_prerelease(), pre.contains(&s), "is_prerelease({s})");
    }
}

#[test]
fn agrees_with_python_packaging_on_every_ordered_pair() {
    let t = truth();
    let mut checked = 0;
    for (pair, want) in t["order"].as_object().unwrap() {
        let (a, b) = pair.split_once(' ').unwrap();
        let want = match want.as_i64().unwrap() {
            -1 => Ordering::Less,
            0 => Ordering::Equal,
            _ => Ordering::Greater,
        };
        let got = Version::parse(a).unwrap().cmp(&Version::parse(b).unwrap());
        assert_eq!(got, want, "{a} vs {b}");
        checked += 1;
    }
    assert!(checked > 4000, "{checked} pairs");
}

#[test]
fn agrees_with_python_packaging_on_every_specifier_match() {
    let t = truth();
    let valid = strings(&t["valid"]);
    let mut checked = 0;
    for (spec, accepted) in t["matches"].as_object().unwrap() {
        let set = SpecifierSet::parse(spec).unwrap_or_else(|| panic!("specifier {spec:?} should parse"));
        let accepted = strings(accepted);
        for v in &valid {
            let got = set.matches(&Version::parse(v).unwrap());
            assert_eq!(got, accepted.contains(v), "does {spec:?} accept {v}?");
            checked += 1;
        }
    }
    assert!(checked > 2500, "{checked} checks");
}

#[test]
fn agrees_with_python_packaging_on_every_marker() {
    let t = truth();
    let mut env = Env::cpython_linux("3.11.4", "x86_64");
    for (k, v) in t["env"].as_object().unwrap() {
        let key = env.0.keys().find(|have| **have == k.as_str()).copied().unwrap_or_else(|| panic!("unknown env key {k}"));
        env.0.insert(key, v.as_str().unwrap().to_string());
    }
    for (marker, want) in t["markers"].as_object().unwrap() {
        match want.as_bool() {
            Some(want) => assert_eq!(evaluate(marker, &env), Ok(want), "{marker}"),
            None => assert!(evaluate(marker, &env).is_err(), "{marker} is an error in Python"),
        }
    }
}
